def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, remaining_qty)]
    sell_book = []  # [(price, arrival_time, id, remaining_qty)]
    next_arrival_time = 0
    order_map = {}  # id -> (side, index_in_book) for tracking resting orders

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_index = order_map[order_id]
                book = buy_book if side == 'buy' else sell_book
                if book_index < len(book) and book[book_index][2] == order_id:
                    book[book_index] = None  # Mark as cancelled
                del order_map[order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[3] if order_type == 'market' else order[4]
        price = order[3] if order_type != 'market' else None

        if side == 'buy':
            # Match against sell book
            while qty > 0 and sell_book:
                # Remove None entries from front
                while sell_book and sell_book[0] is None:
                    sell_book.pop(0)

                if not sell_book:
                    break

                sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                # Check if match is possible
                if order_type == 'market' or price >= sell_price:
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])
                    qty -= trade_qty
                    sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                    if sell_book[0][3] == 0:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                else:
                    break

            # Add to book if limit order or ioc/market with remaining qty
            if order_type == 'limit' or (qty > 0 and order_type == 'ioc'):
                if qty > 0:
                    buy_book.append((price, next_arrival_time, order_id, qty))
                    order_map[order_id] = ('buy', len(buy_book) - 1)

            # For IOC, remaining qty is discarded
            # For market, remaining qty is discarded

        else:  # sell
            # Match against buy book
            while qty > 0 and buy_book:
                # Remove None entries from front
                while buy_book and buy_book[0] is None:
                    buy_book.pop(0)

                if not buy_book:
                    break

                # Find best match: highest price, then earliest arrival
                best_idx = 0
                for i in range(1, len(buy_book)):
                    if buy_book[i] is not None:
                        if (buy_book[i][0] > buy_book[best_idx][0] or
                            (buy_book[i][0] == buy_book[best_idx][0] and buy_book[i][1] < buy_book[best_idx][1])):
                            best_idx = i

                if buy_book[best_idx] is None:
                    break

                buy_price, buy_arrival, buy_id, buy_qty = buy_book[best_idx]

                # Check if match is possible
                if order_type == 'market' or price <= buy_price:
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])
                    qty -= trade_qty
                    buy_book[best_idx] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

                    if buy_book[best_idx][3] == 0:
                        buy_book[best_idx] = None
                        if buy_id in order_map:
                            del order_map[buy_id]
                else:
                    break

            # Add to book if limit order with remaining qty
            if order_type == 'limit' and qty > 0:
                sell_book.append((price, next_arrival_time, order_id, qty))
                order_map[order_id] = ('sell', len(sell_book) - 1)

        next_arrival_time += 1

    return trades

